using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;
public static class InputFoundationChecks {
 public static void Run(){int n=0;Action<bool,string> check=(ok,name)=>{if(!ok)throw new Exception("FAIL "+name);n++;};
 for(int i=0;i<6;i++){var r=new ModifierPressOwnership();var x=r.Sample(1<<i,1<<i,false,false,true);check(x.attackMask==(1<<i)&&x.pulses.Length==0,"ordinary immediate slot "+i);x=r.Sample(1<<i,0,true,false,true);check(x.attackMask==0&&!x.forceHeld&&x.pulses.Length==0,"modifier later cannot reinterpret "+i);r.Sample(0,0,true,false,true);x=r.Sample(1<<i,1<<i,true,false,true);check(x.attackMask==0,"modifier owns press "+i);if(i==2)check(x.forceHeld,"Force chord held");else check(x.pulses.Length==1,"modified pulse once "+i);x=r.Sample(1<<i,0,true,false,true);check(x.pulses.Length==0&&x.attackMask==0,"no hold repeat "+i);x=r.Sample(1<<i,0,false,false,true);check(!x.forceHeld&&x.attackMask==0&&x.pulses.Length==0,"modifier release no fallback "+i);r.Sample(0,0,false,false,true);x=r.Sample(1<<i,1<<i,false,false,true);check(x.attackMask==(1<<i),"repress returns to ordinary "+i);}
 foreach(int i in new[]{0,3,4}){var x=new ModifierPressOwnership().Sample(1<<i,1<<i,true,false,false);check(x.attackMask==0&&x.pulses.Length==0,"training chord inert outside training "+i);}
 var both=new ModifierPressOwnership().Sample(4,4,true,true,true);check(!both.forceHeld&&both.attackMask==0&&both.pulses.Length==0,"no invented T1+T2 action");
 var empty=new ModifierPressOwnership().Sample(1,1,false,true,true);check(empty.attackMask==0&&empty.pulses.Length==0,"unassigned T2 inert");
 var force=new ModifierPressOwnership();check(force.Sample(4,4,true,false,true).forceHeld,"same frame modifier Force priority");check(!force.Sample(0,0,true,false,true).forceHeld,"face release stops Force");force.Sample(4,4,true,false,true);force.Clear();check(force.Sample(0,0,false,false,true).attackMask==0,"clear drops all ownership");
 string error;check(!ModifierPressOwnership.ValidateBindings("<Gamepad>/leftTrigger","",new[]{"<Gamepad>/leftTrigger"},out error),"modifier normal conflict rejected");check(!ModifierPressOwnership.ValidateBindings("a","A",new string[0],out error),"same modifiers rejected");check(ModifierPressOwnership.ValidateBindings("<Gamepad>/leftTrigger","",new[]{"<Gamepad>/buttonWest"},out error),"unassigned T2 valid");check(!ModifierPressOwnership.ValidateChords(new[]{"Battle:T1:B","Battle:T1:B"},out error),"duplicate context chord rejected");check(ModifierPressOwnership.ValidateChords(new[]{"Battle:T1:B","Menu:T1:B"},out error),"distinct contexts may reuse chord");
 var slots=CharacterAttackSlot.AwariDefaults();check(CharacterAttackSlot.Validate(slots,out error),"Awari six slots valid");check(string.Join("/",slots.Select(x=>x.displayName))=="LP/MP/HP/LK/MK/HK","Awari labels");slots[0].displayName="OtherName";check(slots[0].displayName!="LP","character label data editable");slots[1].slot=BattleAttackSlot.A;check(!CharacterAttackSlot.Validate(slots,out error),"duplicate character slot rejected");
 string result=n+" PASS, 0 FAIL (unwired foundation only)";var args=Environment.GetCommandLineArgs();int j=Array.IndexOf(args,"-inputFoundationReport");if(j>=0)File.WriteAllText(args[j+1],result);Debug.Log(result);PublicSnapshotChecks.Verify();}
}
